    rb->len++;
    return true;
}

bool rb_pop(ringbuf *rb, int *out) {
    if (rb->len == 0) return false;
    *out = rb->data[rb->head];
    rb->head = (rb->head + 1) % rb->cap;
    rb->len--;
    return true;
}

bool rb_peek(const ringbuf *rb, size_t i, int *out) {
    if (i >= rb->len) return false;
    *out = rb->data[(rb->head + i) % rb->cap];
    return true;
}

